#!/usr/bin/env node
// Patch the installed Paykit React Native package for React Native 0.80+.
// Runs from npm postinstall and is safe to run again.
//
// Why: the package's Android JNI adapter (cpp-adapter.cpp) was generated by
// uniffi-bindgen-react-native 0.29.3-1. It reaches the JS call invoker by
// reading the `mHybridData` field of CallInvokerHolderImpl. React Native 0.80
// turned that class into an fbjni HybridClassBase without that field, so the
// app aborts at startup with "no ... field mHybridData". ubrn main unwraps the
// holder with fbjni instead (jhugman/uniffi-bindgen-react-native#295, #298).
// This applies the same change. The adapter is compiled by the app's own
// Android build, so no Rust rebuild is needed.
//
// We cannot use patch-package: it re-downloads the package from npm, and this
// package is installed from a local tarball.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const file = join(root, 'node_modules/@synonymdev/react-native-paykit/android/cpp-adapter.cpp');
const MARKER = 'paykit-wdk-wallet: fbjni call invoker';

let source = readFileSync(file, 'utf8');
if (source.includes(MARKER)) {
  console.log('patch-paykit: cpp-adapter.cpp already patched');
  process.exit(0);
}

const start = source.indexOf('    // https://github.com/realm/realm-js');
const end = source.indexOf('    auto runtime = reinterpret_cast<jsi::Runtime *>(rtPtr);\n    return synonymdev_reactnativepaykit::installRustCrate');
if (start < 0 || end < 0 || !source.includes('#include <ReactCommon/CallInvokerHolder.h>\n')) {
  console.error('patch-paykit: cpp-adapter.cpp does not look as expected; update scripts/patch-paykit.mjs');
  process.exit(1);
}

const replacement = `    // ${MARKER} (see scripts/patch-paykit.mjs).
    using JCallInvokerHolder = facebook::react::CallInvokerHolder;
    auto holderLocal = facebook::jni::make_local(callInvokerHolderJavaObj);
    auto holderRef = facebook::jni::static_ref_cast<JCallInvokerHolder::javaobject>(holderLocal);
    auto jsCallInvoker = holderRef->cthis()->getCallInvoker();

`;
source = source.slice(0, start) + replacement + source.slice(end);
source = source.replace(
  '#include <ReactCommon/CallInvokerHolder.h>\n',
  '#include <ReactCommon/CallInvokerHolder.h>\n#include <fbjni/fbjni.h>\n',
);
writeFileSync(file, source);
console.log('patch-paykit: patched cpp-adapter.cpp for React Native 0.80+');
